export function DivElement({
  text = "{{text}}",
  bg = "{{bg}}",
  padding = {{padding}},
  radius = "{{radius}}",
}) {
  const corner = { square: 0, rounded: 12, pill: 999 }[radius] ?? 12;
  return (
    <div style={{ width: 320, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430" }}>
      <p style={{ margin: "0 0 12px", color: "#241430aa", fontSize: 13 }}>
        A <code style={{ background: "#24143012", padding: "1px 5px", borderRadius: 4 }}>&lt;div&gt;</code> carries no meaning of its own — it is purely a box for layout and styling
      </p>
      <div style={{ background: bg, padding, borderRadius: corner, fontWeight: 600, textAlign: "center", boxSizing: "border-box" }}>{text}</div>
    </div>
  );
}
